// @vitest-size large
// Spawns the script with child_process, which the medium guard blocks.
import { spawnSync } from 'node:child_process'
import { mkdtempSync, rmSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { fileURLToPath } from 'node:url'

import {
  changedVersions,
  newPackages,
  packageNames
} from './lockfile-new-packages.mjs'

// A lockfile shaped like the real one: quoted descriptor lists, a workspace
// entry, an npm alias, a patch entry and `__metadata`.
const lockfile = (entries: string[]) =>
  [
    '# This file is generated by running "yarn install" inside your project.',
    '# Manual changes might be lost - proceed with caution!',
    '',
    '__metadata:',
    '  version: 10',
    '  cacheKey: 10c0',
    '',
    ...entries
  ].join('\n')

const entry = (key: string, version: string, resolution: string) =>
  [
    `"${key}":`,
    `  version: ${version}`,
    `  resolution: "${resolution}"`,
    ''
  ].join('\n')

// Yarn writes a key longer than 1024 characters as `? "…"` + `: …` lines.
const longKeyEntry = (key: string, version: string, resolution: string) =>
  [
    `? "${key}"`,
    `: version: ${version}`,
    `  resolution: "${resolution}"`,
    ''
  ].join('\n')

const workspace = entry(
  '@activities/pg@workspace:packages/pg',
  '0.0.0-use.local',
  '@activities/pg@workspace:packages/pg'
)

const base = lockfile([
  workspace,
  entry(
    '@babel/code-frame@npm:^7.10.4, @babel/code-frame@^7.29.7',
    '7.29.7',
    '@babel/code-frame@npm:7.29.7'
  ),
  entry('react-is-18@npm:react-is@^18.3.1', '18.3.1', 'react-is@npm:18.3.1'),
  entry('zod@npm:^4.0.0', '4.0.0', 'zod@npm:4.0.0')
])

describe('lockfile package names', () => {
  it('reads scoped and unscoped names from a real-looking lockfile', () => {
    expect([...packageNames(base)].sort()).toEqual([
      '@babel/code-frame',
      'react-is',
      'zod'
    ])
  })

  it('ignores __metadata and workspace entries', () => {
    const names = packageNames(base)

    expect(names.has('__metadata')).toBe(false)
    expect(names.has('@activities/pg')).toBe(false)
    expect(names.has('@workspace:packages/pg')).toBe(false)
  })

  it('counts the real package behind an npm alias', () => {
    const aliased = lockfile([
      entry('react-is-19@npm:react-is@^19.2.5', '19.2.5', 'react-is@npm:19.2.5')
    ])

    expect([...packageNames(aliased)]).toEqual(['react-is'])
  })

  it('counts a builtin compat patch under its package name', () => {
    const patched = lockfile([
      entry(
        'typescript@patch:typescript@npm%3A7.0.2#optional!builtin<compat/typescript>',
        '7.0.2',
        'typescript@patch:typescript@npm%3A7.0.2#optional!builtin<compat/typescript>'
      ),
      entry(
        'fsevents@patch:fsevents@npm%3A2.3.3#optional!builtin<compat/fsevents>',
        '2.3.3',
        'fsevents@patch:fsevents@npm%3A2.3.3#optional!builtin<compat/fsevents>::version=2.3.3&hash=df0bf1'
      ),
      entry(
        'typescript@patch:typescript@npm%3A7.0.2#optional!builtin<compat/typescript>',
        '7.0.2',
        'typescript@patch:typescript@npm%3A7.0.2#optional!builtin<compat/typescript>::version=7.0.2&hash=3bafbf'
      )
    ])

    expect([...packageNames(patched)].sort()).toEqual([
      'fsevents',
      'typescript'
    ])
  })

  it('reads the resolution of an entry whose key is written as ? "…" + : lines', () => {
    const long = lockfile([
      longKeyEntry(
        `${'@scope/long-name@npm:^1.0.0, '.repeat(40)}@scope/long-name@npm:^1.0.0`,
        '1.0.0',
        '@scope/long-name@npm:1.0.0'
      )
    ])

    expect([...packageNames(long)]).toEqual(['@scope/long-name'])
  })

  it('normalises CRLF line endings', () => {
    const crlf = lockfile([
      entry('zod@npm:^4.0.0', '4.0.0', 'zod@npm:4.0.0')
    ]).replace(/\n/g, '\r\n')

    expect([...packageNames(crlf)]).toEqual(['zod'])
  })
})

describe('new packages between two lockfiles', () => {
  it('reports nothing when only versions moved', () => {
    const head = lockfile([
      workspace,
      entry(
        '@babel/code-frame@npm:^7.10.4, @babel/code-frame@^7.30.0',
        '7.30.0',
        '@babel/code-frame@npm:7.30.0'
      ),
      entry(
        'react-is-18@npm:react-is@^18.3.1',
        '18.3.1',
        'react-is@npm:18.3.1'
      ),
      entry('zod@npm:^4.1.0', '4.1.0', 'zod@npm:4.1.0')
    ])

    expect(newPackages(base, head)).toEqual([])
  })

  it('does not report a package the head lockfile dropped', () => {
    const head = lockfile([
      workspace,
      entry(
        '@babel/code-frame@npm:^7.10.4, @babel/code-frame@^7.29.7',
        '7.29.7',
        '@babel/code-frame@npm:7.29.7'
      )
    ])

    expect(newPackages(base, head)).toEqual([])
  })

  it('reports the names head gained, sorted', () => {
    const head = lockfile([
      workspace,
      entry(
        '@babel/code-frame@npm:^7.10.4, @babel/code-frame@^7.29.7',
        '7.29.7',
        '@babel/code-frame@npm:7.29.7'
      ),
      entry(
        'react-is-18@npm:react-is@^18.3.1',
        '18.3.1',
        'react-is@npm:18.3.1'
      ),
      entry('zod@npm:^4.0.0', '4.0.0', 'zod@npm:4.0.0'),
      entry('@scope/new@npm:^1.0.0', '1.0.0', '@scope/new@npm:1.0.0'),
      entry('another@npm:^2.0.0', '2.0.0', 'another@npm:2.0.0')
    ])

    expect(newPackages(base, head)).toEqual(['@scope/new', 'another'])
  })

  it('does not report an alias whose target the base lockfile has', () => {
    const head = lockfile([
      workspace,
      entry(
        '@babel/code-frame@npm:^7.10.4, @babel/code-frame@^7.29.7',
        '7.29.7',
        '@babel/code-frame@npm:7.29.7'
      ),
      entry(
        'react-is-18@npm:react-is@^18.3.1',
        '18.3.1',
        'react-is@npm:18.3.1'
      ),
      entry('zod@npm:^4.0.0', '4.0.0', 'zod@npm:4.0.0'),
      entry('react-is-19@npm:react-is@^19.2.5', '19.2.5', 'react-is@npm:19.2.5')
    ])

    expect(newPackages(base, head)).toEqual([])
  })

  it('reports the real name a chained alias resolves to', () => {
    const head = lockfile([
      workspace,
      entry(
        '@babel/code-frame@npm:^7.10.4, @babel/code-frame@^7.29.7',
        '7.29.7',
        '@babel/code-frame@npm:7.29.7'
      ),
      entry(
        'react-is-18@npm:react-is@^18.3.1',
        '18.3.1',
        'react-is@npm:18.3.1'
      ),
      entry('zod@npm:^4.0.0', '4.0.0', 'zod@npm:4.0.0'),
      entry(
        'alias@npm:react-is@npm:new-pkg@^1.0.0',
        '1.0.0',
        'new-pkg@npm:1.0.0'
      )
    ])

    expect(newPackages(base, head)).toEqual(['new-pkg'])
  })

  it('reports a new package whose key is written as ? "…" + : lines', () => {
    const head = lockfile([
      workspace,
      entry(
        '@babel/code-frame@npm:^7.10.4, @babel/code-frame@^7.29.7',
        '7.29.7',
        '@babel/code-frame@npm:7.29.7'
      ),
      entry(
        'react-is-18@npm:react-is@^18.3.1',
        '18.3.1',
        'react-is@npm:18.3.1'
      ),
      entry('zod@npm:^4.0.0', '4.0.0', 'zod@npm:4.0.0'),
      longKeyEntry(
        `${'@scope/long-name@npm:^1.0.0, '.repeat(40)}@scope/long-name@npm:^1.0.0`,
        '1.0.0',
        '@scope/long-name@npm:1.0.0'
      )
    ])

    expect(newPackages(base, head)).toEqual(['@scope/long-name'])
  })

  it('reports a new package when the head lockfile uses CRLF', () => {
    const head = lockfile([
      workspace,
      entry(
        '@babel/code-frame@npm:^7.10.4, @babel/code-frame@^7.29.7',
        '7.29.7',
        '@babel/code-frame@npm:7.29.7'
      ),
      entry(
        'react-is-18@npm:react-is@^18.3.1',
        '18.3.1',
        'react-is@npm:18.3.1'
      ),
      entry('zod@npm:^4.0.0', '4.0.0', 'zod@npm:4.0.0'),
      entry('@scope/new@npm:^1.0.0', '1.0.0', '@scope/new@npm:1.0.0')
    ]).replace(/\n/g, '\r\n')

    expect(newPackages(base, head)).toEqual(['@scope/new'])
  })

  it('does not report a builtin compat patch of a package the base has', () => {
    const head = lockfile([
      workspace,
      entry(
        '@babel/code-frame@npm:^7.10.4, @babel/code-frame@^7.29.7',
        '7.29.7',
        '@babel/code-frame@npm:7.29.7'
      ),
      entry(
        'react-is-18@npm:react-is@^18.3.1',
        '18.3.1',
        'react-is@npm:18.3.1'
      ),
      entry(
        'zod@patch:zod@npm%3A4.0.0#optional!builtin<compat/zod>',
        '4.0.0',
        'zod@patch:zod@npm%3A4.0.0#optional!builtin<compat/zod>'
      )
    ])

    expect(newPackages(base, head)).toEqual([])
  })

  it('does not report a version bump of a builtin compat patch with ::version&hash', () => {
    const before = lockfile([
      workspace,
      entry(
        'fsevents@patch:fsevents@npm%3A2.3.3#optional!builtin<compat/fsevents>',
        '2.3.3',
        'fsevents@patch:fsevents@npm%3A2.3.3#optional!builtin<compat/fsevents>::version=2.3.3&hash=df0bf1'
      ),
      entry(
        'typescript@patch:typescript@npm%3A7.0.2#optional!builtin<compat/typescript>',
        '7.0.2',
        'typescript@patch:typescript@npm%3A7.0.2#optional!builtin<compat/typescript>::version=7.0.2&hash=3bafbf'
      )
    ])
    const after = lockfile([
      workspace,
      entry(
        'fsevents@patch:fsevents@npm%3A2.3.4#optional!builtin<compat/fsevents>',
        '2.3.4',
        'fsevents@patch:fsevents@npm%3A2.3.4#optional!builtin<compat/fsevents>::version=2.3.4&hash=abcdef'
      ),
      entry(
        'typescript@patch:typescript@npm%3A7.0.3#optional!builtin<compat/typescript>',
        '7.0.3',
        'typescript@patch:typescript@npm%3A7.0.3#optional!builtin<compat/typescript>::version=7.0.3&hash=1234ab'
      )
    ])

    expect(newPackages(before, after)).toEqual([])
  })

  it.each([
    ['a tarball URL', 'pkg@https://example.com/pkg-1.0.0.tgz'],
    [
      'a tarball URL whose path contains @workspace:',
      'pkg@https://example.com/@workspace:pkg-1.0.0.tgz'
    ],
    [
      'an __archiveUrl',
      'pkg@npm:1.0.0::__archiveUrl=https%3A%2F%2Fexample.com'
    ],
    ['a file: source', 'pkg@file:./vendor/pkg'],
    ['an exec: source', 'pkg@exec:./scripts/build-pkg.js'],
    ['a custom patch', 'pkg@patch:pkg@npm%3A1.0.0#./pkg.patch'],
    [
      'a builtin compat patch with a second &-joined patch',
      'pkg@patch:pkg@npm%3A1.0.0#optional!builtin<compat/pkg>&./pkg.patch'
    ],
    [
      'a builtin compat patch with a second ,-joined patch',
      'pkg@patch:pkg@npm%3A1.0.0#optional!builtin<compat/pkg>,./pkg.patch'
    ],
    [
      'a builtin compat patch of another package',
      'pkg@patch:other@npm%3A1.0.0#optional!builtin<compat/other>'
    ],
    [
      'a builtin compat patch with an encoded __archiveUrl',
      'pkg@patch:pkg@npm%3A1.0.0%3A%3A__archiveUrl%3Dhttps%253A%252F%252Fexample.com%252Fpkg.tgz#optional!builtin<compat/pkg>::version=1.0.0&hash=3bafbf'
    ],
    [
      'a builtin compat patch with unencoded :: in the inner version',
      'pkg@patch:pkg@npm%3A1.0.0::__archiveUrl=https://example.com#optional!builtin<compat/pkg>'
    ],
    [
      'a builtin compat patch with extra trailing query parameters',
      'pkg@patch:pkg@npm%3A1.0.0#optional!builtin<compat/pkg>::version=1.0.0&hash=3bafbf&extra=1'
    ],
    ['a non-registry npm: git spec', 'pkg@npm:git+https://x/r.git'],
    ['a non-registry npm: URL spec', 'pkg@npm:https://x/p.tgz']
  ])('reports %s under an existing name as new', (_label, locator) => {
    const withPkg = lockfile([
      workspace,
      entry('pkg@npm:^1.0.0', '1.0.0', 'pkg@npm:1.0.0')
    ])
    const head = lockfile([
      workspace,
      entry('pkg@npm:^1.0.0', '1.0.0', locator)
    ])

    expect(newPackages(withPkg, head)).toEqual([locator])
  })

  it.each([
    ['an invalid npm package name', '--registry=https://x/@npm:1.0.0'],
    ['a git+https npm: version', 'zod@npm:git+https://x/r.git'],
    ['an https tarball npm: version', 'zod@npm:https://x/p.tgz']
  ])('reports %s as a full-locator new source', (_label, locator) => {
    const head = lockfile([
      workspace,
      entry('zod@npm:^4.0.0', '4.0.0', locator)
    ])

    expect(newPackages(base, head)).toEqual([locator])
  })
})

describe('changed versions between two lockfiles', () => {
  it('reports nothing when the versions did not move', () => {
    expect(changedVersions(base, base)).toEqual([])
  })

  it('reports a bumped version as name@version', () => {
    const head = lockfile([
      workspace,
      entry('zod@npm:^4.1.0', '4.1.0', 'zod@npm:4.1.0')
    ])

    expect(changedVersions(base, head)).toEqual(['zod@4.1.0'])
  })

  it('reports the version of a package the base lockfile does not have', () => {
    const head = lockfile([
      workspace,
      entry('zod@npm:^4.0.0', '4.0.0', 'zod@npm:4.0.0'),
      entry('@scope/new@npm:^1.0.0', '1.0.0', '@scope/new@npm:1.0.0')
    ])

    expect(changedVersions(base, head)).toEqual(['@scope/new@1.0.0'])
  })

  it('reports the real package behind an npm alias', () => {
    const head = lockfile([
      workspace,
      entry('zod@npm:^4.0.0', '4.0.0', 'zod@npm:4.0.0'),
      entry('react-is-19@npm:react-is@^19.2.5', '19.2.5', 'react-is@npm:19.2.5')
    ])

    expect(changedVersions(base, head)).toEqual(['react-is@19.2.5'])
  })

  it.each([
    ['a tarball URL', 'pkg@https://example.com/pkg-1.0.0.tgz'],
    [
      'an __archiveUrl',
      'pkg@npm:1.0.0::__archiveUrl=https%3A%2F%2Fexample.com'
    ],
    ['a file: source', 'pkg@file:./vendor/pkg'],
    ['a custom patch', 'pkg@patch:pkg@npm%3A1.0.0#./pkg.patch'],
    [
      'a builtin compat patch',
      'pkg@patch:pkg@npm%3A1.0.0#optional!builtin<compat/pkg>'
    ],
    [
      'a builtin compat patch with ::version&hash',
      'typescript@patch:typescript@npm%3A7.0.2#optional!builtin<compat/typescript>::version=7.0.2&hash=3bafbf'
    ],
    ['an invalid npm package name', '--registry=https://x/@npm:1.0.0'],
    ['a git+https npm: version', 'zod@npm:git+https://x/r.git'],
    ['an https tarball npm: version', 'zod@npm:https://x/p.tgz']
  ])('ignores %s, which is not a registry version', (_label, locator) => {
    const head = lockfile([
      workspace,
      entry('pkg@npm:^1.0.0', '1.0.0', locator)
    ])

    expect(changedVersions(base, head)).toEqual([])
  })
})

describe('lockfile-new-packages CLI', () => {
  it('prints one name per line and exits 0', () => {
    const directory = mkdtempSync(join(tmpdir(), 'lockfile-new-packages-'))
    try {
      const basePath = join(directory, 'base.lock')
      const headPath = join(directory, 'head.lock')
      writeFileSync(basePath, base)
      writeFileSync(
        headPath,
        lockfile([
          workspace,
          entry(
            '@babel/code-frame@npm:^7.10.4, @babel/code-frame@^7.29.7',
            '7.29.7',
            '@babel/code-frame@npm:7.29.7'
          ),
          entry(
            'react-is-18@npm:react-is@^18.3.1',
            '18.3.1',
            'react-is@npm:18.3.1'
          ),
          entry('zod@npm:^4.0.0', '4.0.0', 'zod@npm:4.0.0'),
          entry('@scope/new@npm:^1.0.0', '1.0.0', '@scope/new@npm:1.0.0')
        ])
      )

      const script = fileURLToPath(
        new URL('./lockfile-new-packages.mjs', import.meta.url)
      )
      const result = spawnSync(process.execPath, [script, basePath, headPath], {
        encoding: 'utf8'
      })

      expect(result.status).toBe(0)
      expect(result.stdout).toBe('@scope/new\n')
    } finally {
      rmSync(directory, { recursive: true, force: true })
    }
  })

  it('prints the changed versions with --changed-versions', () => {
    const directory = mkdtempSync(join(tmpdir(), 'lockfile-new-packages-'))
    try {
      const basePath = join(directory, 'base.lock')
      const headPath = join(directory, 'head.lock')
      writeFileSync(basePath, base)
      writeFileSync(
        headPath,
        lockfile([
          workspace,
          entry('zod@npm:^4.1.0', '4.1.0', 'zod@npm:4.1.0'),
          entry('@scope/new@npm:^1.0.0', '1.0.0', '@scope/new@npm:1.0.0')
        ])
      )

      const script = fileURLToPath(
        new URL('./lockfile-new-packages.mjs', import.meta.url)
      )
      const result = spawnSync(
        process.execPath,
        [script, '--changed-versions', basePath, headPath],
        { encoding: 'utf8' }
      )

      expect(result.status).toBe(0)
      expect(result.stdout).toBe('@scope/new@1.0.0\nzod@4.1.0\n')
    } finally {
      rmSync(directory, { recursive: true, force: true })
    }
  })
})
